#!/bin/bash

#######################################################################
#  This file is automatically generated if it does not already exist.
#######################################################################

#Tech Support script version
TS_VERSION="1.0.1"

# TRUE=0, FALSE=1
TRUE=0
FALSE=1

# Device Serial Number
SN=$(dmidecode -s chassis-serial-number)
if [ ! $? -eq 0 ]; then
    SN=""
elif [[ $SN = *" "* ]]; then
    #SN contains space charachater inside
    SN=""
fi

# DATESTR: The format of log folder and log file
DATESTR=$(date +"%Y%m%d%H%M%S")
LOG_FOLDER_NAME=""
LOG_FILE_NAME=""

# LOG_FOLDER_ROOT: The root folder of log files
LOG_FOLDER_ROOT=""
LOG_FOLDER_PATH=""
LOG_FILE_PATH=""
LOG_FAST=${FALSE}

# BSP_INIT_FLAG: set by function _check_bsp_init
BSP_INIT_FLAG=""

SCRIPTPATH="$( cd -- "$(dirname "$0")" >/dev/null 2>&1 ; pwd -P )"

# LOG_FILE_ENABLE=1: Log all the platform info to log files (${LOG_FILE_NAME})
# LOG_FILE_ENABLE=0: Print all the platform info in console
LOG_FILE_ENABLE=1

# HEADER_PROMPT=1 :print file name at log file first line
# HEADER_PROMPT=0 :don't print file name at log file first line
HEADER_PROMPT=1

# ls option
# LS_OPTION="-alu"                 : show all file, file permission, list time and sort it by name
# LS_OPTION="-a | cat | sort"      : list one filename per output line and sort it
LS_OPTION="-alu"

# Log Redirection
# LOG_REDIRECT="2> /dev/null"        : remove the error message from console
# LOG_REDIRECT=""                    : show the error message in console
# LOG_REDIRECT="2>&1"                : show the error message in stdout, then stdout may send to console or file in _echo()
LOG_REDIRECT=""

# Err Log Redirection
LOG_ERR_REDIRECT=""

# I2C Bus
I801_BUS=""
ISMT_BUS=""

# Execution Time
start_time=$(date +%s)
end_time=0
elapsed_time=0

# Options
OPT_BYPASS_I2C_COMMAND=${FALSE}

# Default Platform Variables
MODEL_NAME="NA"
MODEL_ID="NA"
DEPH_ID="NA"
HW_REV_ID="NA"
BUILD_REV_ID="NA"

#################################
#  Platform Specific Block
#################################

# PLAT: This script is compatible with the platform.
PLAT=""

S3IP_CONFIG_FILE="${SCRIPTPATH}/../s3ip_config.yml"
BIOS_BOOT_SEL_REG=""
BIOS_BOOT_SEL_REG_MASK=""
IOPORT_ADDRESS=()

# root_bus,
# grandparent address,grandparent channel,
# parent address,parent channel,
# dev,bus (the initialized bus),addr
CPLD_I2C_POSITION=()

# description,ver_reg,build_reg
# ex: "CPU CPLD,0x600,0x6e0"
# ex: "CPLD1,0x702,0x704"
CPLD_DEV_LPC=()

I2C_DEV_INFO=()

# bus
# grandparent address,grandparent channel,
# parent address,parent channel,
# name, channel number, address
I2C_TREE=()

# bus
# grandparent address,grandparent channel,
# parent address,parent channel,
# address
SYS_EEPROM=""

#  "<ko_name>,<module_name>"
DRIVER_ARRAY=(
   "i2c-smbus.ko,i2c_smbus"
)

BMC_SUPPORT=0
BMC_DEV_STAT_SUPPORT_VER=0
BMC_SEL_RAW_DATA_SUPPORT_VER=0

UCD_BRD=""
UVD_SUPPORT_VER=0

ROV_SUPPORT_VER=0
CPLD_INTR_SUPPORT_VER=0
CPLD_ERR_LOG_SUPPORT_VER=0
BEACON_LED_SUPPORT_VER=0
MEM_CORRECTABLE_ERROR_COUNT_SUPPORT_VER=0
#######################################################################

function _echo {
    local str="$@"

    if [ "${LOG_FILE_ENABLE}" == "1" ] && [ -f "${LOG_FILE_PATH}" ]; then
        echo "${str}" >> "${LOG_FILE_PATH}"
    else
        echo "${str}"
    fi
}

function _printf {
    if [ "${LOG_FILE_ENABLE}" == "1" ] && [ -f "${LOG_FILE_PATH}" ]; then
        printf "$@" >> "${LOG_FILE_PATH}"
    else
        printf "$@"
    fi
}

function _banner {
   local banner="$1"

   if [ ! -z "${banner}" ]; then
       _echo ""
       _echo "##############################"
       _echo "#   ${banner}"
       echo  "#   ${banner}..."
       _echo "##############################"
   fi
}

function _plat_ts_version {
    echo ""
}

function _pkg_version {
    _banner "Package Version"
    _echo "Package Version = ${TS_VERSION}"
    _echo "Platform Configuration Version = $(_plat_ts_version)"
}

function _show_ts_version {
    echo "Package Version = ${TS_VERSION}"
    echo "Platform Configuration Version = $(_plat_ts_version)"
}

function _dd_read_byte {
    local reg=$1
    echo "0x"`dd if=/dev/port bs=1 count=1 skip=$((reg)) status=none | xxd -g 1 | cut -d ' ' -f 2`
}

# -----------------------------------------------------------------------------
# Parse YAML block by capturing lines deeper than the header's indentation.
# Args: $1 = Content String (NOT file path), $2 = Block Name
# -----------------------------------------------------------------------------
function _parse_yaml_block {
    local contents="$1"
    local block="$2"
    awk -v target="$block" '
                $0 ~ "^[ \t]*" target ":" {
                    in_block = 1
                    match($0, /[^ \t]/)
                    indent_len = RSTART - 1
                    print $0
                    next
                }

                in_block {
                    if (NF == 0) { print; next }
                    match($0, /[^ \t]/)
                    current_indent = RSTART - 1
                    if (NF == 0) { print; next }
                    if (current_indent > indent_len) {
                        print $0
                    } else {
                        exit
                    }
                }
            '<<< "$contents"
}

# -----------------------------------------------------------------------------
# _get_yaml_attr_value: Retrieves a value from a YAML file using a dot-separated path.
# Logic: Iteratively drills down blocks (e.g., "a.b.c") and extracts the final clean value.
# Usage: _get_yaml_attr_value <attr_path>
# -----------------------------------------------------------------------------
function _get_yaml_attr_value {
    local attrs="$1"
    local attr_array=(${attrs//./ })

    [ ! -f "$S3IP_CONFIG_FILE" ] && return 0
    local contents="$(cat "$S3IP_CONFIG_FILE")"
    for attr in "${attr_array[@]}"; do
        contents=$(_parse_yaml_block "$contents" "$attr")
    done
    echo "$contents" |
        grep -E "^[[:space:]]*${attr}:" |
        sed "s/^[[:space:]]*${attr}:[[:space:]]*//" |
        tr -d '"'
}

function _check_env {
    #_banner "Check Environment"

    # check basic commands
    local cmd_array=("ipmitool" "lsusb" "dmidecode")
    for (( i=0; i<${#cmd_array[@]}; i++ ))
    do
        ret=`which ${cmd_array[$i]}`

        if [ ! $? -eq 0 ]; then
            _echo "${cmd_array[$i]} command not found!!"
            exit 1
        fi
    done

    if [ "${LOG_FILE_ENABLE}" == "1" ]; then
        mkdir -p "${LOG_FOLDER_PATH}"

        if [ ! -d "${LOG_FOLDER_PATH}" ]; then
            _echo "[ERROR] invalid log path: ${LOG_FOLDER_PATH}"
            exit 1
        fi

        if [ "${HEADER_PROMPT}" == "1" ]; then
            echo "${LOG_FILE_NAME}" > "${LOG_FILE_PATH}"
        else
            touch "${LOG_FILE_PATH}"
        fi
    fi

    # get i2c root
    _get_i2c_root
    if [ ! -z ${I801_BUS} ]; then
        _echo "[I801 bus ]: ${I801_BUS}"
    fi

    if [ ! -z ${ISMT_BUS} ]; then
        _echo "[ismt bus ]: ${ISMT_BUS}"
    fi

    # check BSP init
    _check_bsp_init

    # Set platform specific variables
    if declare -F "_set_plat_vars" > /dev/null; then
        _set_plat_vars
    fi
}

function _check_filepath {
    local filepath=$1
    local silent="${2:-0}"

    if [ -z "${filepath}" ]; then
        if [ "$silent" = "0" ]; then
            _echo "ERROR, the input string is empty!!!"
        fi
        return ${FALSE}
    elif [ ! -f "$filepath" ]; then
        if [ "$silent" = "0" ]; then
            _echo "ERROR: No such file: ${filepath}"
        fi
        return ${FALSE}
    else
        #_echo "File Path: ${filepath}"
        return ${TRUE}
    fi
}

function _check_dirpath {
    local dirpath=$1
    if [ -z "${dirpath}" ]; then
        _echo "ERROR, the ipnut string is empty!!!"
        return ${FALSE}
    elif [ ! -d "$dirpath" ]; then
        _echo "ERROR: No such directory: ${dirpath}"
        return ${FALSE}
    else
        return ${TRUE}
    fi
}

function _check_i2c_device {
    local i2c_bus=$1
    local i2c_addr=$2

    if [ -z "${i2c_addr}" ]; then
        _echo "ERROR, the input string is empty!!!"
        return ${FALSE}
    fi

    local value=$(eval "i2cget -y -f ${i2c_bus} ${i2c_addr} ${LOG_ERR_REDIRECT}")
    local ret=$?

    if [ $ret -eq 0 ]; then
        return ${TRUE}
    else
        _echo "ERROR: No such device: Bus:${i2c_bus}, Address: ${i2c_addr}"
        return ${FALSE}
    fi
}

function _check_bsp_init {
    _banner "Check BSP Init"

    # As our bsp init status, we look at S3IP slot model_name.
    if [ -f "/sys_switch/slot/slot1/model_name" ]; then
        BSP_INIT_FLAG=1
    else
        BSP_INIT_FLAG=0
    fi

    _echo "[BSP_INIT_FLAG]: ${BSP_INIT_FLAG}"
}

function _get_i2c_root {
    local i2c_0=""
    local i2c_1=""

    if _check_filepath "/sys/bus/i2c/devices/i2c-0/name" ;then
        i2c_0=`cat /sys/bus/i2c/devices/i2c-0/name`
    fi

    if _check_filepath "/sys/bus/i2c/devices/i2c-1/name" ;then
        i2c_1=`cat /sys/bus/i2c/devices/i2c-1/name`
    fi

    if echo "$i2c_0" | grep -q "I801"; then
        I801_BUS=0
    fi

    if echo "$i2c_1" | grep -q "I801"; then
        I801_BUS=1
    fi

    if echo "$i2c_0" | grep -q "iSMT"; then
        ISMT_BUS=0
    fi

    if echo "$i2c_1" | grep -q "iSMT"; then
        ISMT_BUS=1
    fi
}

function _show_system_info {
    _banner "Show System Info"
    local i=0
    local x86_date=`date`
    local x86_uptime=`uptime`
    local bmc_date=$(eval "ipmitool sel time get ${LOG_REDIRECT}")
    local last_login=`last`

    _echo "[X86 Date Time ]: ${x86_date}"
    _echo "[BMC Date Time ]: ${bmc_date}"
    _echo "[X86 Up Time   ]: ${x86_uptime}"
    _echo "[X86 Last Login]: "
    _echo "${last_login}"
    _echo ""

    local cmd_array=("uname -a" "cat /proc/cmdline" "cat /proc/ioports" \
               "cat /proc/iomem" "cat /proc/meminfo" \
               "cat /proc/sys/kernel/printk" \
               "find /etc -name '*-release' -print -exec cat {} \;")

    for (( i=0; i<${#cmd_array[@]}; i++ ))
    do
        _echo "[Command]: ${cmd_array[$i]}"
        local ret=$(eval "${cmd_array[$i]} ${LOG_REDIRECT}")
        _echo "${ret}"
        _echo ""
    done

}

