function _pre_log {
    _banner "Pre Log"

    _show_i2c_tree_bus
    _show_i2c_tree_bus
    _show_i2c_tree_bus
}

function read_s3ip_sysfs_int {
    local sysfs=$1
    local default_value=$2

    if _check_filepath "${sysfs}"; then
        local reg_value=$(eval "cat ${sysfs}")
        # check if reg_value is integer
        if [[ "$reg_value" =~ ^-?[0-9]+$ ]]; then
            echo $reg_value
        else
            echo $default_value
        fi
    else
        echo $default_value
    fi
}

function read_s3ip_sysfs {
    local sysfs=$1
    local default_value=$2

    if [[ -z "$2" ]]; then
        default_value=""
    fi

    if _check_filepath "${sysfs}"; then
        local reg_value=$(eval "cat ${sysfs}")
            echo $reg_value
    else
        echo $default_value
    fi
}

function _show_board_info {
    _banner "Show Board Info"

    local build_rev_array=(1 2 3 4 5 6 7 8)
    local hw_rev_id_array=(0 1 2 3)
    local hw_rev_array=("Proto" "Alpha" "Beta" "PVT")
    local hw_rev_ga_array=("GA_1" "GA_2" "GA_3" "GA_4")
    local deph_name_array=("NPI" "GA")

    local deph_name=${deph_name_array[${DEPH_ID}]}
    if [ $DEPH_ID -eq 0 ]; then
        HW_REV=${hw_rev_array[${HW_REV_ID}]}
    else
        HW_REV=${hw_rev_ga_array[${HW_REV_ID}]}
    fi

    local build_rev=${build_rev_array[${BUILD_REV_ID}]}

    _echo "[Model Name       ]: ${MODEL_NAME} ($(printf "0x%x" $MODEL_ID))"
    _echo "[Hardware Revision]: ${HW_REV} ($(printf "0x%x" $HW_REV_ID))"
    _echo "[Build Revision   ]: ${build_rev} ($(printf "0x%x" $BUILD_REV_ID))"
    _echo "[Design Phase     ]: ${deph_name} ($(printf "0x%x" $DEPH_ID))"

    # extra board infomation
    if declare -F "_show_extra_info" > /dev/null; then
