    fi
}

function _bios_boot_rom_bit {
    if [ -z "$BIOS_BOOT_SEL_REG" ]; then
        return 0
    fi

    local reg=${BIOS_BOOT_SEL_REG%%,*}
    local bit=${BIOS_BOOT_SEL_REG##*,}
    local bios_boot_sel=$(_dd_read_byte $reg)
    bios_boot_sel=$(( (bios_boot_sel & (1 << bit)) >> bit ))
    _echo "[BIOS Boot ROM]: ${bios_boot_sel}"
}

function _bios_boot_rom_mask {
    if [ -z "$BIOS_BOOT_SEL_REG_MASK" ]; then
        return 0
    fi

    local reg=""
    local mask=""
    local offset=""

    IFS=',' read -r \
        reg \
        mask \
        offset \
        <<< "$BIOS_BOOT_SEL_REG_MASK"

    local bios_boot_sel=$(_dd_read_byte $reg)
    bios_boot_sel=$(( (bios_boot_sel & (mask)) >> offset ))
    _echo "[BIOS Boot ROM]: ${bios_boot_sel}"
}

function _bios_version {
    _banner "Show BIOS Version"

    local bios_ver=$(eval "cat /sys/class/dmi/id/bios_version ${LOG_REDIRECT}")
    _echo "[BIOS Version ]: ${bios_ver}"
    _bios_boot_rom_bit
    _bios_boot_rom_mask
}

function _bmc_version {
    _banner "Show BMC Version"

    local bmc_rom1_ver=$(eval "ipmitool raw 0x32 0x8f 0x8 0x1 ${LOG_REDIRECT}")
    local bmc_rom2_ver=$(eval "ipmitool raw 0x32 0x8f 0x8 0x2 ${LOG_REDIRECT}")
    local bmc_active_rom=$(eval "ipmitool raw 0x32 0x8f 0x7 ${LOG_REDIRECT}")

    _echo "[BMC ROM1 Ver  ]: ${bmc_rom1_ver}"
    _echo "[BMC ROM2 Ver  ]: ${bmc_rom2_ver}"
    _echo "[BMC Active ROM]: ${bmc_active_rom}"
}

function _cpld_version_lpc {

    if ! declare -p CPLD_DEV_LPC 2>/dev/null | grep -q 'declare -[aA]' || [ "${#CPLD_DEV_LPC[@]}" -eq 0 ]; then
        return 0
    fi

    _banner "Show CPLD Version (LPC)"

    local cpld_name="" ver_reg="" build_reg=""
    local cpld_ver="" cpld_build="" range=""

    for range in "${CPLD_DEV_LPC[@]}"; do
        IFS=',' read -r cpld_name ver_reg build_reg <<< "$range"

        cpld_ver=$(_dd_read_byte $ver_reg)
        cpld_build=$(_dd_read_byte $build_reg)
        _printf "[${cpld_name} Version]: %d.%02d.%03d\n" $(( (cpld_ver & 2#11000000) >> 6)) $(( cpld_ver & 2#00111111 )) $((cpld_build))
    done
}

function _cpld_version_i2c {
    if [ "${OPT_BYPASS_I2C_COMMAND}" == "${TRUE}" ]; then
        _banner "Show CPLD Version (I2C) (Bypass)"
        return 0
    fi

    if ! declare -p CPLD_I2C_POSITION 2>/dev/null | grep -q 'declare -[aA]' || [ "${#CPLD_I2C_POSITION[@]}" -eq 0 ]; then
        return 0
    fi

    _banner "Show CPLD Version (I2C)"

    local root_bus=""
    local grandparent_addr="" grandparent_chann=""
    local parent_addr="" parent_chann=""
    local dev="" bus="" addr=""
    local range=""

    for range in "${CPLD_I2C_POSITION[@]}"; do
        IFS=',' read -r \
            root_bus \
            grandparent_addr \
            grandparent_chann \
            parent_addr \
            parent_chann \
            dev \
            bus \
            addr \
            <<< "$range"

        if [ -n "${grandparent_addr}" ] && \
            [ -n "${grandparent_chann}" ]; then
            if _check_i2c_device "${root_bus}" "${grandparent_addr}"; then
                i2cset -y -f ${root_bus} ${grandparent_addr} "$(( 1 << grandparent_chann ))"
                grandparent_existed=1
            fi
        fi

        if [ -n "${parent_addr}" ] && \
            [ -n "${parent_chann}" ]; then
            if _check_i2c_device "${root_bus}" "${parent_addr}"; then
                i2cset -y -f ${root_bus} ${parent_addr} "$(( 1 << parent_chann))"
                parent_existed=1
            fi
        fi

        local cpld_ver="" cpld_build=""

        if _check_i2c_device "${root_bus}" "${addr}"; then
            cpld_ver=$(eval "i2cget -y -f ${root_bus} ${addr} 0x2 ${LOG_ERR_REDIRECT}")
            cpld_build=$(eval "i2cget -y -f ${root_bus} ${addr} 0x4 ${LOG_ERR_REDIRECT}")
            cpld_ver=${cpld_ver:-0}
            cpld_build=${cpld_build:-0}
            _printf "[${dev^^} Version]: %d.%02d.%03d\n" $(( (cpld_ver & 2#11000000) >> 6)) $(( cpld_ver & 2#00111111 )) $((cpld_build))
        fi

        if [ "$parent_existed" = "1" ]; then
            i2cset -y -f ${root_bus} ${parent_addr} 0x0
            parent_existed=0
        fi

        if [ "$grandparent_existed" = "1" ]; then
            i2cset -y -f ${root_bus} ${grandparent_addr} 0x0
            grandparent_existed=0
        fi
    done
}

function _cpld_version_sysfs {
    _banner "Show CPLD Version (Sysfs)"

    local num_cplds=0

    # MB CPLD
    num_cplds=$(read_s3ip_sysfs_int "/sys_switch/cpld/number" 0)
    for (( idx=1; idx<=${num_cplds}; idx++ )); do
        local cpld_name=""
        local cpld_ver=""

        cpld_name=$(read_s3ip_sysfs "/sys_switch/cpld/cpld${idx}/description" "CPLD${idx}")
        cpld_ver=$(read_s3ip_sysfs "/sys_switch/cpld/cpld${idx}/firmware_version" "")

        _echo "[${cpld_name} Version]: ${cpld_ver}"
    done

    # MB FPGA
    local num_fpgas=0

    num_fpgas=$(read_s3ip_sysfs_int "/sys_switch/fpga/number" 0)
    for (( idx=1; idx<=${num_fpgas}; idx++ )); do
        local fpga_name=""
        local fpga_ver=""

        fpga_name=$(read_s3ip_sysfs "/sys_switch/fpga/fpga${idx}/description" "FPGA${idx}")
        fpga_ver=$(read_s3ip_sysfs "/sys_switch/fpga/fpga${idx}/firmware_version" "")

        _echo "[${fpga_name} Version]: ${fpga_ver}"
    done
}

function _cpld_version {
    if [ "${BSP_INIT_FLAG}" == "1" ]; then
        _cpld_version_sysfs
    else
        _cpld_version_lpc
        _cpld_version_i2c
    fi
}

function _ucd_version_v1 {
    if ! declare -p UCD_BRD 2>/dev/null | grep -q 'declare -[aA]' || [ "${#UCD_BRD[@]}" -eq 0 ]; then
        return 0
    fi

    _banner "Show UCD Version"

    #get ucd version via BMC
    local ucd_ver_raw=$(eval "ipmitool raw 0x3c 0x8 0x0 ${LOG_ERR_REDIRECT}")
    local ret=$?

    #check return code
    if [ ! $ret -eq 0 ] ; then
        _echo "Require BMC v2.02 or later to get UCD version"
        return $ret
    fi

    #convert hex to ascii
    local ucd_ver_ascii=`echo $ucd_ver_raw | xxd -r -p`

    #get ucd date via BMC
    local ucd_date_raw=$(eval "ipmitool raw 0x3c 0x8 0x1 ${LOG_ERR_REDIRECT}")
    ret=$?

    #check return code
    if [ ! $ret -eq 0 ] ; then
        _echo "Require BMC v2.02 or later to get UCD version"
        return $ret
    fi

    #convert hex to ascii
    local ucd_date_ascii=`echo $ucd_date_raw | xxd -r -p`

    _echo "[${UCD_BRD[i]} UCD REVISION RAW]: ${ucd_ver_raw}"
    _echo "[${UCD_BRD[i]} UCD DATE RAW    ]: ${ucd_date_raw}"
    _echo "[${UCD_BRD[i]} MFR_REVISION    ]: ${ucd_ver_ascii}"
    _echo "[${UCD_BRD[i]} MFR_DATE        ]: ${ucd_date_ascii}"
}

function _ucd_version {
    case "$UVD_SUPPORT_VER" in
        1)
            _ucd_version_v1
            ;;
        *)
            ;;
    esac
    return 0
}

function _show_version {
    _bios_version
    _bmc_version
    _cpld_version
}

function _show_i2c_tree_bus {

    if [ ! -z ${I801_BUS} ]; then
        _banner "Show I2C Tree Bus I801"

        local ret=$(eval "(time i2cdetect -y ${I801_BUS}) ${LOG_REDIRECT}")

        _echo "[I2C Tree ${I801_BUS}]:"
        _echo "${ret}"
    fi

    if [ ! -z ${ISMT_BUS} ]; then
        _banner "Show I2C Tree Bus ISMT"

        local ret=$(eval "(time i2cdetect -y ${ISMT_BUS}) ${LOG_REDIRECT}")

        _echo "[I2C Tree ${ISMT_BUS}]:"
        _echo "${ret}"
    fi

}

function _show_i2c_mux_devices {
    local bus=$1
    local chip_addr=$2
    local channel_num=$3
    local chip_dev_desc=$4
    local is_ch=${5:-false}
    local i=0;
    local startc=0;
    local endc=0;

    if [ -z "${bus}" ] || \
        [ -z "${chip_addr}" ] || \
        [ -z "${channel_num}" ] || \
        [ -z "${chip_dev_desc}" ]; then
        _echo "ERROR: parameter cannot be empty!!!"
        return 1
    fi

    if [ "$is_ch" = "true" ]; then
        startc=${channel_num}
        endc=$(( ${channel_num} + 1 ))
    else
        startc=0
        endc=${channel_num}
    fi

    if _check_i2c_device "$bus" "$chip_addr"; then
        _echo "TCA954X Mux ${chip_dev_desc}"
        _echo "---------------------------------------------------"
        for (( i=startc; i<${endc}; i++ ))
        do
            _echo "TCA954X Mux ${chip_dev_desc} - Channel ${i}"

            # open mux channel
            if ! i2cset -y "$bus" "$chip_addr" "$(( 1 << i ))"; then
                _echo "Error: Failed to switch to channel $i"
                continue
            fi

            # dump i2c tree
            ret=$(eval "(time i2cdetect -y ${bus}) ${LOG_REDIRECT}")
            _echo "${ret}"
            # close mux channel
            i2cset -y ${bus} ${chip_addr} 0x0
            _echo ""
        done
    fi
}

function _show_i2c_tree_bus_mux_i2c {
    if [ "${OPT_BYPASS_I2C_COMMAND}" == "${TRUE}" ]; then
        _banner "Show I2C Tree Bus MUX (I2C) (Bypass)"
        return 0
    fi

    if ! declare -p I2C_TREE 2>/dev/null | grep -q 'declare -[aA]' || [ "${#I2C_TREE[@]}" -eq 0 ]; then
        return 0
    fi

    _banner "Show I2C Tree Bus MUX (I2C)"

    for range in "${I2C_TREE[@]}"; do
        local bus=""
        local grandparent_addr="" grandparent_chann=""
        local parent_addr="" parent_chann=""
        local name channel_num="" addr=""
        local grandparent_existed=0
        local parent_existed=0
        IFS=',' read -r \
            bus \
            grandparent_addr \
            grandparent_chann \
            parent_addr \
            parent_chann \
            name \
            channel_num \
            addr \
            <<< "$range"

        if [ -n "${grandparent_addr}" ] && \
            [ -n "${grandparent_chann}" ]; then
            i2cset -y "${bus}" "${grandparent_addr}" "$(( 1 << grandparent_chann ))"
            grandparent_existed=1
        fi

        if [ -n "${parent_addr}" ] && \
            [ -n "${parent_chann}" ]; then
            i2cset -y "${bus}" "${parent_addr}" "$(( 1 << parent_chann))"
            parent_existed=1
        fi

        _show_i2c_mux_devices "${bus}" "${addr}" "${channel_num}" "${name}"

        if [ "$parent_existed" = "1" ];then
            i2cset -y "${bus}" "${parent_addr}" 0
            parent_existed=0
        fi

        if [ "$grandparent_existed" = "1" ];then
            i2cset -y "${bus}" "${grandparent_addr}" 0
            grandparent_existed=0
        fi
    done
}

function _show_i2c_tree {
    _banner "Show I2C Tree"

    _show_i2c_tree_bus

    if [ "${BSP_INIT_FLAG}" == "1" ]; then
