function _show_i2c_device_info {

    if ! declare -p I2C_DEV_INFO 2>/dev/null | grep -q 'declare -[aA]' || [ "${#I2C_DEV_INFO[@]}" -eq 0 ]; then
        return 0
    fi

    local range=""
    _banner "Show I2C Device Info"
    for range in "${I2C_DEV_INFO[@]}"; do
        local bus=${range%%,*}
        local addr=${range##*,}
        local j=0
        for ((j=0;j<5;j++))
        do
            ret=`i2cget -f -y ${bus} ${addr}`
            _printf "%-20s: %s\n" "[I2C Device ${addr} (${j})]" "$ret"
        done
        sleep 0.4
    done
}

