function _show_sys_eeprom_i2c {
    if ! declare -p SYS_EEPROM &>/dev/null; then
        return 0
    fi

    local bus=""
    local grandparent_addr="" grandparent_chann=""
    local parent_addr="" parent_chann=""
    local addr=""
    local grandparent_existed=0
    local parent_existed=0
    local sys_eeprom=""

    if [ "${OPT_BYPASS_I2C_COMMAND}" == "${TRUE}" ]; then
        _banner "Show System EEPROM (I2C) (Bypass)"
        return 0
    fi

    _banner "Show System EEPROM (I2C)"

    IFS=',' read -r \
        bus \
        grandparent_addr \
        grandparent_chann \
        parent_addr \
        parent_chann \
        addr \
        <<< "$SYS_EEPROM"

    if [ -n "${grandparent_addr}" ] && \
        [ -n "${grandparent_chann}" ]; then
        i2cset -y "${bus}" "${grandparent_addr}" "$(( 1 << grandparent_chann ))"
        grandparent_existed=1
    fi

    if [ -n "${parent_addr}" ] && \
        [ -n "${parent_chann}" ]; then
        i2cset -y "${bus}" "${parent_addr}" "$(( 1 << parent_chann))"
        parent_existed=1
    fi

    local j=0
    # Reset offset to 0 and ensure data integrity.
    for ((j=0;j<10;j++))
    do
        sys_eeprom=$(eval "i2cdump -y ${bus} ${addr} c")
    done

    _echo "[System EEPROM]:"
    _echo "${sys_eeprom}"

    if [ "$parent_existed" = "1" ];then
        i2cset -y "${bus}" "${parent_addr}" 0x0
        parent_existed=0
    fi

    if [ "$grandparent_existed" = "1" ]; then
        i2cset -y -f ${bus} ${grandparent_addr} 0x0
        grandparent_existed=0
    fi
}

