function _show_disk_info {
    _banner "Show Disk Info"
    local i=0
    local ret=""
    local root_part=$(awk '$2 == "/" {print $1}' /proc/mounts)
    local storage_name=$(lsblk -n -o pkname "$root_part" | head -n 1)
    local storage="/dev/$storage_name"

    local cmd_array=("lsblk"
               "lsblk -O"
               "parted -s -l"
               "fdisk -l $storage"
               "find /sys/fs/ -name errors_count -print -exec cat {} \;"
               "find /sys/fs/ -name first_error_time -print -exec cat {} \; -exec echo '' \;"
               "find /sys/fs/ -name last_error_time -print -exec cat {} \; -exec echo '' \;"
               "df -h")

    for (( i=0; i<${#cmd_array[@]}; i++ ))
    do
        _echo "[Command]: ${cmd_array[$i]}"
        ret=$(eval "${cmd_array[$i]} ${LOG_REDIRECT}")
        _echo "${ret}"
        _echo ""
    done

    # check smartctl command
    ret=`which smartctl`
    if [ ! $? -eq 0 ]; then
        _echo "[command]: smartctl not found (SKIP)!!"
    else
        local cmd=""
        local disk=""
        local smartctl_commands=(
            "smartctl -a"
            "smartctl -x"
        )
        local target_disks=( $(ls /sys/block/$storage_name/slaves/ 2>/dev/null) )
        if [ "${#target_disks[@]}" -eq 0 ]; then
                target_disks=("$storage_name")
        fi

        for cmd in "${smartctl_commands[@]}"; do
            for disk in "${target_disks[@]}"; do
                ret=$(eval "$cmd /dev/$disk ${LOG_REDIRECT}")
                _echo "[command]: $cmd /dev/$disk"
                _echo "${ret}"
                _echo ""
            done
        done
    fi
}

